using System.Collections.Generic;using UnityEngine;
public sealed class ScytheMotor:INewWeaponMotor {
 readonly NewWeaponCombat owner;GearItem source;float next,end,used,power,tempo;int phase;bool skill,pull,released;public bool Busy{get;private set;}public string Phase{get;private set;}="Idle";public string BasicDescription=>"中距有方向弧形；不包含背后目标";public float Interval=>.8f*owner.BasicTempo;
 public ScytheMotor(NewWeaponCombat owner){this.owner=owner;}
 public bool Begin(bool skill,int slot){this.skill=skill;tempo=skill?1:owner.BasicTempo;pull=skill&&slot==1;source=owner.Combat.Gear.Main.Clone();power=owner.Hero.AttackPower;phase=0;next=Time.time+(pull?.4f:.3f)*tempo;used=0;released=false;Busy=true;Phase="Startup";owner.Cooldown(skill,skill?owner.SkillDuration:Interval);owner.Animate(skill&&!pull?"2H_Melee_Attack_Spin":"2H_Melee_Attack_Slice",skill?1.2f:.75f*tempo,2);owner.Emit("start",0,"scythe",Vector3.zero,Vector3.zero,0,null,0,0,false);return true;}
 public void Tick(){if(!Busy)return;if(Time.time<next){owner.Face(3.3f,25,130,ref used);return;}if(!released){Phase="Release";CombatFeedback.Find(owner)?.PlaySound(CombatSound.ScytheSweep,owner.transform.position,.65f);if(pull)owner.PullSector();else owner.NewSector(source,power*(skill?.45f:.8f),skill?3.4f:3.0f+owner.BasicReachBonus,skill?125:85,false,skill?10+phase:0);owner.Emit("release",phase,"scythe",Vector3.zero,Vector3.zero,0,null,0,0,false);if(skill&&!pull&&phase<2){phase++;next=Time.time+.24f;return;}released=true;end=Time.time+.35f*tempo;}Phase="Recovery";if(Time.time>=end){Busy=false;Phase="Idle";owner.Emit("complete",phase,"scythe",Vector3.zero,Vector3.zero,0,null,0,0,false);}}
 public void Cancel(){if(Busy)owner.Emit("cancel",phase,"scythe",Vector3.zero,Vector3.zero,0,null,0,0,false);Busy=false;Phase="Cancelled";}
}
public sealed partial class NewWeaponCombat {
 internal void PullSector(){var seen=new HashSet<CombatEnemy>();Vector3 center=MeleeGeometry.Center(transform.position);float reach=4.5f*(WeaponTraits.Has(combat.Gear.Main,2)?1.25f:1);foreach(var c in Physics.OverlapSphere(center,reach,~0,QueryTriggerInteraction.Ignore)){if(!CombatAim.Legal(c,hero))continue;var e=c.GetComponentInParent<CombatEnemy>();if(e==null||e.Health.Dead||seen.Contains(e))continue;Vector3 point=CombatAim.OverlapPoint(c,center),delta=Vector3.ProjectOnPlane(point-center,Vector3.up);if(Vector3.Angle(transform.forward,delta)>50)continue;if(!AdventureCombat.Sight(center,point,e)){Emit("pull-obstructed",0,"",center,point,0,e,0,0,false);continue;}seen.Add(e);var control=e.GetComponent<EnemyWeaponControl>()??e.gameObject.AddComponent<EnemyWeaponControl>();bool applied=control.Pull(hero,1);Emit(applied?"pull-start":"control-immune",0,"",center,point,0,e,0,0,false);if(applied)NewWeaponTrace.Capsule(center,point,.05f,gameObject.scene,hero,new Color(.65f,.4f,1));}NewWeaponArc.Show(center,transform.forward,reach,50,gameObject.scene,hero);}
}
